import '../../features/response/domain/response_playbooks.dart';

/// Simplified Chinese incident-response guidance mapped to stable playbook IDs.
class MandarinResponseContent {
  MandarinResponseContent._();
  static const Map<String, Map<String, Object>> _data = {
    'account-compromise': {'title':'账户可能已遭入侵','summary':'您发现未知登录、恢复信息被更改、账户发送了并非由您撰写的消息，或出现意外身份验证请求。','firstAction':'使用另一台可信设备，通过官方应用或已知网址访问相关服务。','steps':['如果主邮箱也受到影响，请优先保护它，因为其他服务通常会通过邮箱重置密码。','更换为独立且强度足够的密码，并启用可用的强身份验证方式。','检查恢复邮箱和电话号码、通行密钥及身份验证方式；移除不认识的项目。','结束未知会话，并在服务允许时撤销未知的已连接应用或令牌。','检查邮件转发规则、筛选器、已发送邮件及账户近期变更。','如果涉及工作或学校账户，请立即通知组织的 IT 或安全团队。'],'preserve':['记录安全提醒邮件、登录时间、设备和会话详情以及账户通知。','在可用时保存原始消息及邮件标头，并记录您何时进行了哪些更改。'],'avoid':['不要向任何声称可以提供帮助的人透露密码、OTP、恢复代码或会话链接。','不要使用意外消息中提供的恢复链接或电话号码。','在记录重要提醒内容之前，不要将其删除。'],'limit':'ORVIKA 不会验证账户访问、结束会话或恢复账户。请遵循服务提供商的官方流程；具体名称和步骤可能不同。'},
    'payment-fraud': {'title':'可疑或未经授权的付款','summary':'您可能在压力下转账、批准了意外付款、泄露了付款信息，或发现未知交易。','firstAction':'立即通过官方应用、银行卡背面的电话或独立核实的网站联系银行或付款服务提供商。','steps':['要求服务提供商保护受影响的账户、银行卡或钱包，并说明争议处理或撤销交易的流程。','报告未经授权的交易或诈骗，并提供交易编号、金额、日期和收款方信息。','使用可信设备更改已泄露的银行和电子邮件密码，并检查会话和付款指令。','如果凭据或 SIM 卡可能遭到入侵，请通知银行和移动运营商。','通过您所在司法管辖区的官方渠道向执法机构报告，并保存案件编号。'],'preserve':['保存交易编号、银行通知、收据、收款方信息、通话记录和消息。','记录发现问题的时间以及联系服务提供商的时间。'],'avoid':['不要向承诺保证追回资金或要求预付款的人付款。','不要批准新的扣款请求、付款指令或远程访问会话。','不要使用疑似诈骗者提供的联系方式。'],'limit':'付款可能无法撤销。ORVIKA 不会冻结账户、追踪资金或提交报案。请立即联系服务提供商。'},
    'lost-device': {'title':'手机、电脑或其他设备丢失','summary':'设备已经丢失、被盗，或可能落入他人手中。','firstAction':'使用另一台可信设备，通过制造商或平台的官方账户安全及设备查找服务采取措施。','steps':['如可行，将设备标记为丢失或远程锁定；结合数据敏感性和找回可能性，谨慎评估是否远程抹除。','联系移动运营商停用 SIM/eSIM 并保护您的电话号码。','如果设备可能处于解锁状态或保存了密码，请更改主邮箱、金融和身份账户的密码。','从另一台受保护设备结束未知会话并检查恢复方式。','向当地有关部门报告疑似盗窃；受管理设备还应遵循组织内部流程。'],'preserve':['保存序列号、适用时的 IMEI、购买凭证和官方安全通知。','记录最后一次看到设备的时间和地点，以及已采取的锁定或报告措施。'],'avoid':['不要与疑似人员对峙，也不要独自前往不安全地点取回设备；请联系主管部门。','不要按要求关闭设备保护或透露账户凭据。','不要把位置估算视为精确结果，也不要据此自行采取不安全行动。'],'limit':'远程查找、锁定和抹除取决于预先设置、网络连接和平台。抹除操作可能影响证据和恢复。'},
    'suspected-malware': {'title':'设备可能感染恶意软件','summary':'设备出现意外弹窗、警告、未知应用、账户异常活动，或打开文件后出现异常行为。','firstAction':'停止在该设备上输入密码和付款信息。如怀疑正在遭受入侵，在可行时断开网络连接。','steps':['使用另一台可信设备更改重要密码；如果是组织设备，请通知安全团队。','不要再次打开可疑文件，也不要根据弹窗或陌生来电的建议安装软件。','使用操作系统内置或来自官方渠道的可信安全工具，并遵循其文档。','评估情况并确认安全后，更新操作系统和应用。','如果凭据可能泄露，请从另一台可信设备更改凭据并结束活动会话。','对于严重事件或工作设备，在清理或重装前保留设备状态并咨询专业人员。'],'preserve':['记录警告文字、文件名、下载来源、时间和安全工具结果。','保存邮件、网址和屏幕截图；不要将敏感文件上传到公开分析服务。'],'avoid':['不要运行来源不明的清理脚本、注册表修复程序或杀毒软件。','在评估调查和恢复需求之前，不要重置设备或删除文件。','不要无必要地连接备份驱动器或其他设备。'],'limit':'这些迹象不能证明设备存在恶意软件。ORVIKA 不会扫描文件或进程，也不会清理设备。严重事件需要专业分析。'},
    'identity-exposure': {'title':'个人信息或身份资料可能泄露','summary':'身份证件、个人信息、账户凭据或非公开记录可能已被不可信的人或服务获取。','firstAction':'确定具体泄露了哪些信息，并保护依赖这些信息的账户和服务。','steps':['使用可信设备更改已泄露及重复使用的密码，并在可用时启用多因素身份验证。','如果身份证件、财务信息或官方凭据泄露，请通过独立核实的渠道联系签发机构。','向金融机构了解监测、更换、限制或其他保护措施。','检查恢复设置，并留意密码重置、信用、交易和身份验证通知。','通过所在司法管辖区的官方隐私渠道、监管机构或执法机构报告事件。'],'preserve':['保存原始通知、通信记录、日期、受影响数据类别和案件编号。','记录已通知的机构以及对方提供的建议或保护措施。'],'avoid':['寻求帮助时，不要公开泄露的证件或完整个人身份号码。','不要向未经核实的恢复服务人员发送更多文件。','不要认为删除帖子或消息就能删除已被复制的内容。'],'limit':'可用的身份保护措施和报告流程取决于数据类型及司法管辖区。ORVIKA 无法判断信息是否已被复制或使用。'}
  };
  static ResponsePlaybook localize(ResponsePlaybook item, String code) {
    if (code != 'zh') return item;
    final v = _data[item.id]; if (v == null) return item;
    return ResponsePlaybook(id:item.id,title:v['title']! as String,scenario:item.scenario,summary:v['summary']! as String,firstAction:v['firstAction']! as String,steps:List<String>.unmodifiable(v['steps']! as List<String>),preserve:List<String>.unmodifiable(v['preserve']! as List<String>),avoid:List<String>.unmodifiable(v['avoid']! as List<String>),limit:v['limit']! as String);
  }
}
